const config = $('Code: Stage Configuration').first().json;
const ENTRY_STAGE_IDS = config.entryStageIds;
const EXIT_STAGE_IDS = config.exitStageIds;
const IRRELEVANT_STAGE_IDS = config.knownIrrelevantStageIds;

function classify(stageId) {
  if (ENTRY_STAGE_IDS.includes(stageId)) return 'entry';
  if (EXIT_STAGE_IDS.includes(stageId)) return 'exit';
  if (IRRELEVANT_STAGE_IDS.includes(stageId)) return 'irrelevant';
  return 'unrecognized';
}

const events = $input.first().json.body;
if (!Array.isArray(events)) {
  return [{ json: { skip: true, reason: "Unexpected payload shape" } }];
}

return events
  .filter(e => e.propertyName === 'dealstage')
  .map(e => ({
    json: { dealId: e.objectId, newStageId: e.propertyValue, classification: classify(e.propertyValue) }
  }))
  .filter(e => e.json.classification !== 'irrelevant');

