const config = $('Code: Stage Configuration').first().json;
const ENTRY_STAGE_IDS = config.entryStageIds;
const EXIT_STAGE_IDS = config.exitStageIds;
const IRRELEVANT_STAGE_IDS = config.knownIrrelevantStageIds;

const deal = $input.first().json;
const assocContainer = deal.associations?.contacts;
const associations = assocContainer?.results ?? assocContainer?.items ?? [];
const contactIds = associations.map(a => a.id || a.toObjectId);

const currentStageId = deal.properties.dealstage;
let currentClassification = 'unrecognized';
if (ENTRY_STAGE_IDS.includes(currentStageId)) currentClassification = 'entry';
else if (EXIT_STAGE_IDS.includes(currentStageId)) currentClassification = 'exit';
else if (IRRELEVANT_STAGE_IDS.includes(currentStageId)) currentClassification = 'irrelevant';

return {
  dealId: deal.id,
  contactIds,
  hasContacts: contactIds.length > 0,
  classification: currentClassification,
  newStageId: currentStageId,
  webhookClaimedClassification: $('Code: Classify Stage Event').first().json.classification
};

