const original = $('Code: Extract Contact IDs').first().json;
const contacts = $input.first().json.contacts || [];
return contacts.map(c => {
    const contactId = c.id;
    const classification = original.classification;
    const idempotencyKey = contactId + ':' + original.dealId + ':' + classification;

    // Grab the email and test if it's a valid string
    const email = (c.properties && c.properties.email) || null;
    const emailLooksValid = typeof email === 'string' && /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email);

    return { 
        json: { 
            ...original, 
            contactId: contactId,
            email: email,
            emailLooksValid: emailLooksValid,
            isSuppressed: c.properties && (c.properties.hs_email_optout === true || c.properties.hs_email_optout === 'true'),
            'Idempotency Key': idempotencyKey 
        } 
    };
});

const logRow = $input.item.json;
const current = $('Code: Prepare Per-Contact Items').item.json;
return { json: { ...current, alreadyApplied: !!logRow['Idempotency Key'] } };

const original = $input.item.json;
const current = original.newRetryCount 
  ?? parseInt(($('Google Sheets: Check Trigger Log').item.json['Retry Count']) || 0, 10);
const statusCode = original.error?.httpCode || original.statusCode || 'unknown';

return {
  json: {
    ...original,
    newRetryCount: current + 1,
    httpStatus: statusCode,
    errorMessage: `[HTTP ${statusCode}] ` + (original.error?.message || JSON.stringify(original).slice(0, 300))
  }
};

