// CENTRALIZED CONFIG: update stage IDs here ONLY.
const ENTRY_STAGE_IDS = ['1121282222', '1121282223', '1121282224', 'qualifiedtobuy', 'decisionmakerboughtin', '1122869089'];
const EXIT_STAGE_IDS = ['1118455408', '1118455409', 'contractsent', 'closedlost'];
const KNOWN_IRRELEVANT_STAGE_IDS = ['1118455404', '1121625098', '1118455407', '1122869087', 'appointmentscheduled', '1122869088'];

return $input.all().map(item => ({
  json: {
    ...item.json,
    entryStageIds: ENTRY_STAGE_IDS,
    exitStageIds: EXIT_STAGE_IDS,
    knownIrrelevantStageIds: KNOWN_IRRELEVANT_STAGE_IDS
  }
}));

// Explicit stateful counter that survives the retry loop
let currentRetryCount = 0;
try {
  const previousRuns = $('Code: Check Batch Completeness').all();
  if (previousRuns && previousRuns.length > 0) {
    currentRetryCount = previousRuns.length;
  }
} catch(e) {}

const reqCount = $('Code: Extract Contact IDs').first().json.contactIds.length;
const results = $('HTTP Request: Batch Read Contacts').first().json.results || [];
const retCount = results.length;
const foundIds = results.map(r => parseInt(r.id));
const missing = $('Code: Extract Contact IDs').first().json.contactIds.filter(id => !foundIds.includes(parseInt(id)));

return {
    json: {
        dealId: $('Code: Extract Contact IDs').first().json.dealId,
        requestedCount: reqCount,
        returnedCount: retCount,
        missingContactIds: missing,
        incomplete: missing.length > 0,
        batchRetryCount: currentRetryCount,
        contacts: results
    }
};

