const crypto = require('crypto');

const input = $input.first().json;
const headers = input.headers || {};
// Ensures the body string is exactly what HubSpot signed, avoiding "[object Object]"
const rawBody = input.rawBody || JSON.stringify(input.body);

const signature = headers['x-hubspot-signature-v3'];
const timestamp = headers['x-hubspot-request-timestamp'];

// Your specific Client Secret for B2
const clientSecret = '476cf9f4-55c6-4042-952d-fecaabfe15de';

let valid = false;
let reason = '';

if (!clientSecret) {
  reason = 'HUBSPOT_CLIENT_SECRET is not configured';
} else if (!signature || !timestamp) {
  reason = 'Missing signature or timestamp header';
} else if (Math.abs(Date.now() - Number(timestamp)) > 5 * 60 * 1000) {
  reason = 'Timestamp too old - possible replay';
} else {
  const method = 'POST';
  // Hardcoded exactly to B2's webhook path to prevent test-mode URL mismatches
  const url = 'https://' + (headers['x-forwarded-host'] || headers.host) + '/webhook/hubspot-deal-stage-change';

  // Notice: The clientSecret is NO LONGER prepended to this string (which was the bug!)
  const base = method + url + rawBody + timestamp;

  const expected = crypto.createHmac('sha256', clientSecret).update(base).digest('base64');

  if (signature.length === expected.length) {
    valid = crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signature));
  }
  if (!valid) reason = 'Signature mismatch';
}

return [{ json: { ...input, signatureValid: valid, signatureFailureReason: reason } }];

